option.value:
// Minimal Win32 GUI implementation - intentionally small and readable so beginners can follow.
// It provides:
// - left panel: file list (enumerates files in ./data)
// - buttons: Create, Open
// - right panel: student list for opened file
// - Add (+) to append a blank student
// - simple edit controls to modify a selected student's fields
// - toolbar buttons: Save, Find, Undo, Redo and keyboard shortcuts

#include "common.h"
#include "../core/student_list.h"
#include "../core/student_process.h"
#include "file_browser.h"
#include "settings.h"
#include "student_editor.h"



static HWND g_mainWnd = NULL;
static char g_openedFilePath[MAX_PATH] = "";

// Forward declarations for helpers implemented in file_browser.c and student_editor.c
void refresh_file_list(HWND hwnd);
int create_new_file_dialog(HWND hwnd, char* outPath, size_t outLen);
int load_students_from_file(const char* path);
int save_students_to_file(const char* path);
void refresh_student_list(HWND hwnd);

LRESULT CALLBACK MainWndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam)
{
	switch (msg)
	{
	case WM_CREATE:
	{
		CreateWindow("STATIC", "Files:", WS_VISIBLE | WS_CHILD, 10, 10, 200, 20, hwnd, NULL, NULL, NULL);
		HWND hFileList = CreateWindow("LISTBOX", NULL, WS_VISIBLE | WS_CHILD | LBS_NOTIFY | WS_BORDER | WS_VSCROLL,
			10, 30, 200, 300, hwnd, (HMENU)IDC_FILE_LIST, NULL, NULL);

		CreateWindow("BUTTON", "Create", WS_VISIBLE | WS_CHILD, 10, 340, 90, 25, hwnd, (HMENU)IDC_CREATE_BTN, NULL, NULL);
		CreateWindow("BUTTON", "Open", WS_VISIBLE | WS_CHILD, 120, 340, 90, 25, hwnd, (HMENU)IDC_OPEN_BTN, NULL, NULL);

		CreateWindow("STATIC", "Students:", WS_VISIBLE | WS_CHILD, 230, 10, 300, 20, hwnd, NULL, NULL, NULL);
		CreateWindow("BUTTON", "+", WS_VISIBLE | WS_CHILD, 520, 8, 30, 24, hwnd, (HMENU)IDC_ADD_BTN, NULL, NULL);
		CreateWindow("LISTBOX", NULL, WS_VISIBLE | WS_CHILD | LBS_NOTIFY | WS_BORDER | WS_VSCROLL,
			230, 30, 320, 300, hwnd, (HMENU)IDC_STUDENT_LIST, NULL, NULL);

		CreateWindow("BUTTON", "Save", WS_VISIBLE | WS_CHILD, 560, 340, 60, 25, hwnd, (HMENU)IDC_SAVE_BTN, NULL, NULL);
		CreateWindow("BUTTON", "Find", WS_VISIBLE | WS_CHILD, 490, 340, 60, 25, hwnd, (HMENU)IDC_FIND_BTN, NULL, NULL);
		CreateWindow("BUTTON", "Undo", WS_VISIBLE | WS_CHILD, 410, 340, 60, 25, hwnd, (HMENU)IDC_UNDO_BTN, NULL, NULL);
		CreateWindow("BUTTON", "Redo", WS_VISIBLE | WS_CHILD, 340, 340, 60, 25, hwnd, (HMENU)IDC_REDO_BTN, NULL, NULL);

		refresh_file_list(hwnd);
	}
	return 0;
	case WM_COMMAND:
	{
		int id = LOWORD(wParam);
		int notify = HIWORD(wParam);
		if (id == IDC_CREATE_BTN && notify == BN_CLICKED)
		{
			char newPath[MAX_PATH] = {0};
			if (create_new_file_dialog(hwnd, newPath, sizeof(newPath)))
			{
				refresh_file_list(hwnd);
			}
		}
		else if (id == IDC_OPEN_BTN && notify == BN_CLICKED)
		{
			HWND hFiles = GetDlgItem(hwnd, IDC_FILE_LIST);
			int idx = (int)SendMessage(hFiles, LB_GETCURSEL, 0, 0);
			if (idx != LB_ERR)
			{
				char fileName[MAX_PATH];
				SendMessage(hFiles, LB_GETTEXT, idx, (LPARAM)fileName);
				// build path relative to ./data
				char buffer[MAX_PATH];
				snprintf(buffer, sizeof(buffer), "data\\%s", fileName);
				if (load_students_from_file(buffer) == 0)
				{
					strncpy_s(g_openedFilePath, sizeof(g_openedFilePath), buffer, _TRUNCATE);
					refresh_student_list(hwnd);
				}
			}
		}
		else if (id == IDC_ADD_BTN && notify == BN_CLICKED)
		{
			// add blank student using core API
			addNode_Tail(&head_p, 0, 0, "", "", "", "", "", 0);
			updatePositions(head_p);
			refresh_student_list(hwnd);
		}
		else if (id == IDC_SAVE_BTN && notify == BN_CLICKED)
		{
			if (g_openedFilePath[0] != '\0') save_students_to_file(g_openedFilePath);
		}
		else if ((id == IDC_FILE_LIST) && notify == LBN_DBLCLK)
		{
			// open file on double click
			HWND hFiles = GetDlgItem(hwnd, IDC_FILE_LIST);
			int idx = (int)SendMessage(hFiles, LB_GETCURSEL, 0, 0);
			if (idx != LB_ERR)
			{
				char fileName[MAX_PATH];
				SendMessage(hFiles, LB_GETTEXT, idx, (LPARAM)fileName);
				char buffer[MAX_PATH];
				snprintf(buffer, sizeof(buffer), "data\\%s", fileName);
				if (load_students_from_file(buffer) == 0)
				{
					strncpy_s(g_openedFilePath, sizeof(g_openedFilePath), buffer, _TRUNCATE);
					refresh_student_list(hwnd);
				}
			}
		}
		else if ((id == IDC_STUDENT_LIST) && (notify == LBN_SELCHANGE))
		{
			HWND hStudents = GetDlgItem(hwnd, IDC_STUDENT_LIST);
			int sel = (int)SendMessage(hStudents, LB_GETCURSEL, 0, 0);
			if (sel != LB_ERR)
			{
				// open editor dialog for this student
				student_edit_dialog(hwnd, sel);
				refresh_student_list(hwnd);
			}
		}
		else if (id == IDC_FIND_BTN && notify == BN_CLICKED)
		{
			settings_show_find_dialog(hwnd);
		}
		else if (id == IDC_UNDO_BTN && notify == BN_CLICKED)
		{
			// placeholder: simple undo not implemented in minimal app
			MessageBox(hwnd, "Undo not implemented in minimal example.", "Info", MB_OK | MB_ICONINFORMATION);
		}
		else if (id == IDC_REDO_BTN && notify == BN_CLICKED)
		{
			MessageBox(hwnd, "Redo not implemented in minimal example.", "Info", MB_OK | MB_ICONINFORMATION);
		}
	}
	return 0;
	case WM_DESTROY:
		PostQuitMessage(0);
		return 0;
	}
	return DefWindowProc(hwnd, msg, wParam, lParam);
}

int app_run(void)
{
	// Initialize common controls (for nicer listbox on some systems)
	INITCOMMONCONTROLSEX icex = { sizeof(icex), ICC_LISTVIEW_CLASSES };
	InitCommonControlsEx(&icex);

	HINSTANCE hInst = GetModuleHandle(NULL);
	WNDCLASS wc = {0};
	wc.lpfnWndProc = MainWndProc;
	wc.hInstance = hInst;
	wc.lpszClassName = "StudentInfoMainWndClass";
	wc.hCursor = LoadCursor(NULL, IDC_ARROW);
	RegisterClass(&wc);

	HWND hwnd = CreateWindow(wc.lpszClassName, "Student Info System", WS_OVERLAPPEDWINDOW,
		CW_USEDEFAULT, CW_USEDEFAULT, 580, 420, NULL, NULL, hInst, NULL);
	if (!hwnd) return -1;
	g_mainWnd = hwnd;
	ShowWindow(hwnd, SW_SHOWNORMAL);

	MSG msg;
	while (GetMessage(&msg, NULL, 0, 0) > 0)
	{
		TranslateMessage(&msg);
		DispatchMessage(&msg);
	}
	return (int)msg.wParam;
}

